package com.afterglow.player;
import android.app.*;import android.graphics.Color;import android.widget.*;import org.json.*;import java.util.*;
/** Lightweight artist-affinity recommendations. Fetches metadata only until explicitly queued. */
final class Recommendations {
 final MainActivity a;Recommendations(MainActivity a){this.a=a;}
 static String seed(PlaybackService s){Map<String,Integer> scores=new LinkedHashMap<>();for(Track t:s.queue)if(!t.artist.trim().isEmpty())scores.put(t.artist,scores.getOrDefault(t.artist,0)+(t.favorite?8:1));if(!s.queue.isEmpty())scores.put(s.current().artist,scores.getOrDefault(s.current().artist,0)+5);ArrayList<String> artists=new ArrayList<>(scores.keySet());artists.sort((x,y)->Integer.compare(scores.get(y),scores.get(x)));if(artists.isEmpty())return "new music official audio";return artists.get(new Random().nextInt(Math.min(3,artists.size())))+" music official audio";}
 void show(){if(a.apiKey.isEmpty()){a.toast("Add your search API key in Settings first");return;}LinearLayout list=a.column();list.setPadding(a.dp(16),a.dp(8),a.dp(16),a.dp(8));TextView status=a.text("Finding songs based on your favourites and library…",14,Color.WHITE);list.addView(status);ScrollView scroll=new ScrollView(a);scroll.addView(list);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Recommended for you").setMessage("Artist-based suggestions. Audio downloads only when you tap Add to queue.").setView(scroll).setNegativeButton("Close",null).show();a.lookup(seed(a.service),20,items->{if(!dialog.isShowing())return;list.removeAllViews();Set<String> seen=new HashSet<>();for(Track t:a.service.queue)seen.add(t.uri);int count=0;for(int i=0;i<items.length()&&count<10;i++)try{JSONObject item=items.getJSONObject(i),snippet=item.getJSONObject("snippet");String id=item.getJSONObject("id").getString("videoId");if(!seen.add(id))continue;Track t=new Track(android.text.Html.fromHtml(snippet.getString("title"),0).toString(),snippet.getString("channelTitle"),id,"youtube");list.addView(a.text(t.title+" · "+t.artist,14,Color.WHITE));Button add=a.button("+ Add to queue",()->{});add.setOnClickListener(v->{if(a.service.upcoming.size()>=PlaybackService.QUEUE_LIMIT){a.toast("Queue is full. Remove a song first.");return;}Track chosen=t;for(Track old:a.service.queue)if(QueueTools.same(old,t)){chosen=old;break;}if(!a.service.queue.contains(chosen))a.service.append(chosen);if(a.service.enqueue(chosen,false)){add.setText("Added to queue");add.setEnabled(false);a.renderSongs();}else a.toast(a.service.error);});list.addView(add);count++;}catch(Exception ignored){}if(count==0)list.addView(a.text("No new suggestions this time. Try again for another artist.",14,Color.WHITE));});}
}
